"use strict";(self.webpackChunknhs_sim=self.webpackChunknhs_sim||[]).push([[256],{4860(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{},"docs":{"api":{"id":"api","title":"API reference","description":"Open the interactive API explorer to browse every published operation, inspect its request schema, and execute requests. Download the OpenAPI 3.1 JSON specification to import it into an API client or give it to an agent. The specification is also available at /openapi.json."},"appointments":{"id":"appointments","title":"Appointment sessions and slots","description":"Open Appointment book in GP Records. Each clinician has AM and PM sessions containing timed slots. The calendar, clinician filter and AM/PM controls change the diary view. All times use the team\'s simulation clock in UTC."},"challenges":{"id":"challenges","title":"Follow one patient across services","description":"Start at the neighbourhood map. Riverside Practice opens GP Records for primary care. Northbank General opens Hospital EPR for secondary care. Use the same team key in both."},"clinical-records":{"id":"clinical-records","title":"Clinical records and hospital orders","description":"GP Records\'s Journal shows dated contacts with their recorded narrative and authors. Search includes note text. Expand Record details and activity to inspect the history or open an action."},"community":{"id":"community","title":"Arrange community visits in Community Care","description":"Open Neighbourhood Care with your team\'s key. Community Care shows upcoming visits, care plans, and the selected person\'s recorded needs and goals."},"data":{"id":"data","title":"The data in your world","description":"Every person in NHS-SIM is fictional. Patient identifiers start with SIM-. The repository does not contain real patient records or production NHS credentials."},"documents":{"id":"documents","title":"Document Inbox and discharge letters","description":"Open Document Inbox, the GP practice\'s document office. It opens as a separate workspace with its own inbox, letter reader and processing panel. The GP building on the neighbourhood map offers separate GP Records and Document Inbox entrances. Hospital teams write discharge summaries in their discharge correspondence workspace and explicitly send them to the GP practice in the same team world."},"fhir":{"id":"fhir","title":"Demographics and organisation APIs","description":"Use the PDS-style API to find a person in your team\'s world, then follow their GP reference into the ODS-style organisation directory. These endpoints return FHIR R4 resource shapes with synthetic identifiers. They implement a documented subset of the NHS APIs."},"home":{"id":"home","title":"Explore home readings in Home Health","description":"Open At home on the neighbourhood map and launch Home Health. The wearable dashboard and patient Messages are separate apps at the same location."},"hospital":{"id":"hospital","title":"Work in Hospital EPR","description":"Open Northbank General with your team\'s key. Hospital EPR opens the Patient List Manager. Select a row to manage an attendance, or select the patient\'s name to enter the chart."},"identity":{"id":"identity","title":"Test staff sign-in with Staff Identity","description":"Staff Identity is the simulator\'s CIS2-style staff identity service. Its staff identities, organisations, and roles are fictional. A staff token does not replace the team API key or grant access to a team world."},"index":{"id":"index","title":"Explore the neighbourhood","description":"A referral gets rejected. A result arrives late. A discharge letter sits in another system. Enter the map, open a workplace, and follow one fictional patient across their care."},"legacy":{"id":"legacy","title":"Transfer a legacy record","description":"The legacy EPR exposes its documents through HTML. /api/sites/legacy/view deliberately returns HTTP 501."},"messaging":{"id":"messaging","title":"Messagey messaging","description":"Messagey is the fictional primary-care messaging workspace beside GP Records and Document Inbox. Open Riverside Practice on the neighbourhood map and choose Messagey. It uses the same team world and patient directory as the other products."},"organisers":{"id":"organisers","title":"Run the event","description":"Start the environment"},"pharmacy":{"id":"pharmacy","title":"Run the pharmacy","description":"Open High Street Pharmacy and connect your team. The pharmacy uses the same patients and team world as the EPRs. Its prices, suppliers, and stock are fictional."},"population":{"id":"population","title":"The synthetic population","description":"The large population is generated in reproducible batches. Each new person has a fictional identity, age-appropriate circumstances, conditions, contact preferences, a structured GP record, three to eight dated consultations and a historical appointment. The original authored patients and team work remain available."},"quickstart":{"id":"quickstart","title":"Make your first API call","description":"Create a team at the map, copy its API key, and open Riverside Practice to enter GP Records. The key stays available in Team & API key in the fixed bottom bar. Read Team access and simulation time for browser setup."},"systemtwo":{"id":"systemtwo","title":"Working in GP Records","description":"Open GP Records with your team key. Search for a person by name, local ID, condition or care need."},"team-access":{"id":"team-access","title":"Team access and simulation time","description":"Create or reconnect a team"},"telephony":{"id":"telephony","title":"Reception Calls","description":"Open Reception Calls from the Riverside Practice desktop. Connect to the same team world as your colleagues, then enter your receptionist name. Each open call desk appears as a separate team member."},"ten-year-plan":{"id":"ten-year-plan","title":"Explore the ten-year plan","description":"Read the ten-year health plan for England, then bring a problem that interests you into the virtual neighbourhood."}}}}')}}]);